    }
    for (int i = this.inputLayers.size() - 1; i >= 0; --i) {
        this.inputLayers.get(i).draw(guiGraphics, mouseX, mouseY);
    }
    if (DebugConfig.isDebugGuisEnabled()) {
        this.drawDebugInfoForScreen(screen, guiGraphics);
    }
}

