private final List<IIngredientGridSource.SourceListChangedListener> listeners = new ArrayList<IIngredientGridSource.SourceListChangedListener>();
private boolean searchIndexDirty;
private boolean sortIndexesDirty;

public IngredientFilter(IFilterTextSource filterTextSource, IClientConfig clientConfig, IIngredientFilterConfig config, IIngredientManager ingredientManager, Function<List<IListElementInfo<?>>, Comparator<IListElement<?>>> sortIndexUpdater, List<IListElementInfo<?>> ingredients, IModIdHelper modIdHelper, IIngredientVisibility ingredientVisibility, IColorHelper colorHelper, ISearchStorageBuilderFactory searchStorageBuilderFactory, IClientToggleState clientToggleState) {
    this.filterTextSource = filterTextSource;
    this.clientConfig = clientConfig;
    this.ingredientManager = ingredientManager;
    this.sortIndexUpdater = sortIndexUpdater;
    this.ingredientComparator = sortIndexUpdater.apply(ingredients);
    this.modIdHelper = modIdHelper;
    this.ingredientVisibility = ingredientVisibility;
    this.elementPrefixParser = new ElementPrefixParser(ingredientManager, config, colorHelper, modIdHelper, searchStorageBuilderFactory);
    this.elementSearch = IngredientFilter.createElementSearch(clientConfig, this.elementPrefixParser, ingredients, ingredientManager);
    this.addConfigListeners(clientConfig, config);
    LOGGER.info("Adding {} ingredients", (Object)ingredients.size());
    for (IListElementInfo<?> ingredient : ingredients) {
        this.updateHiddenState(ingredient.getElement());
    }
    this.invalidateCache();
    LOGGER.info("Added {} ingredients", (Object)ingredients.size());
    if (DebugConfig.isLogSuffixTreeStatsEnabled()) {
        this.elementSearch.logStatistics();
    }
    this.filterTextSource.addListener(filterText -> {
        this.invalidateCache();
        this.notifyListenersOfChange();
    });
    clientToggleState.addEditModeToggleListener(this);
}

private void addConfigListeners(IClientConfig clientConfig, IIngredientFilterConfig config) {
    clientConfig.addLowMemorySlowSearchEnabledListener(v -> this.markSearchIndexDirty());
    clientConfig.addIngredientSorterStagesListener(v -> this.markSortIndexesDirty());
    config.addSearchConfigListener(this::markSearchIndexDirty);
}

private static IElementSearch createElementSearch(IClientConfig clientConfig, ElementPrefixParser elementPrefixParser, List<IListElementInfo<?>> elementInfos, IIngredientManager ingredientManager) {
    if (clientConfig.isLowMemorySlowSearchEnabled()) {
        return new ElementSearchLowMem(elementPrefixParser.getNoPrefix(), elementInfos);
    }
    return new ElementSearch(elementPrefixParser, elementInfos, ingredientManager);
}

public <V> void addIngredient(IListElementInfo<V> info) {
    IListElement<V> element = info.getElement();
    this.updateHiddenState(element);
    this.elementSearch.add(info, this.ingredientManager);

