package mezz.jei.gui.recipes;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Optional;

final class NavigationHistory<T> {
    private final Deque<T> backwardHistory = new ArrayDeque<T>();
    private final Deque<T> forwardHistory = new ArrayDeque<T>();

    NavigationHistory() {
    }

    public void record(T value) {
        this.backwardHistory.push(value);
        this.forwardHistory.clear();
    }

    public Optional<T> goBack(T currentValue) {
        T previousValue = this.backwardHistory.poll();
        if (previousValue == null) {
            return Optional.empty();
        }
        this.forwardHistory.push(currentValue);
        return Optional.of(previousValue);
    }

    public Optional<T> goForward(T currentValue) {
        T nextValue = this.forwardHistory.poll();
        if (nextValue == null) {
            return Optional.empty();
        }
        this.backwardHistory.push(currentValue);
        return Optional.of(nextValue);
    }

    public void clear() {
        this.backwardHistory.clear();
        this.forwardHistory.clear();
    }
}

